import{_ as e,o as d,c as o,a2 as r}from"./chunks/framework.CGSzHL4z.js";const c=JSON.parse('{"title":"Keyboard shortcuts","description":"","frontmatter":{},"headers":[],"relativePath":"reference/shortcuts.md","filePath":"reference/shortcuts.md","lastUpdated":1791952279000}'),i={name:"reference/shortcuts.md"};function a(s,t,n,h,l,b){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h1><p>Every default key. Change them in Settings &gt; Shortcuts.</p><h3 id="how-keys-work" tabindex="-1">How keys work <a class="header-anchor" href="#how-keys-work" aria-label="Permalink to &quot;How keys work&quot;">​</a></h3><ul><li><kbd>Ctrl+Z</kbd> and <kbd>Ctrl+Y</kbd> are Studio&#39;s undo and redo. Every AcesMotion edit is a step, poses included, and Edit &gt; Undo names it.</li><li>Keys are ignored while a text box has focus.</li><li>On a Mac, <kbd>Cmd</kbd> works wherever these pages say <kbd>Ctrl</kbd> (snapping flips, multi-select, shortcuts).</li></ul><div class="warning custom-block"><p class="custom-block-title">Keys Studio keeps</p><p>Some keys never reach a plugin, so the defaults avoid them:</p><ul><li><kbd>Delete</kbd>. It does arrive in the Timeline, because the Timeline sets Studio&#39;s selection aside.</li><li><kbd>Ctrl+C</kbd>, <kbd>Ctrl+V</kbd>, <kbd>Ctrl+X</kbd>, <kbd>Ctrl+D</kbd> and <kbd>Shift+X</kbd>.</li><li><kbd>O</kbd>, <kbd>,</kbd> and <kbd>.</kbd> (Studio&#39;s camera keys).</li><li>Any key you or another plugin bound in Studio&#39;s File &gt; Customize Shortcuts. Those are global, and a plugin cannot read them.</li></ul><p>That is why copy is <kbd>Shift+C</kbd>, paste and duplicate are <kbd>Shift+V</kbd> / <kbd>Shift+D</kbd>, the frame steps are the arrows, and loop in and out are <kbd>Shift+I</kbd> / <kbd>Shift+O</kbd>.</p></div><h4 id="rebinding" tabindex="-1">Rebinding <a class="header-anchor" href="#rebinding" aria-label="Permalink to &quot;Rebinding&quot;">​</a></h4><ul><li>Every shortcut can be rebound in Settings &gt; Shortcuts. Right click a row to clear it or reset it.</li><li>The hold keys also have a field on their own page: <ul><li>Temporary pivot key, Pin key (<kbd>Shift</kbd> plus it clears pins), IK / FK switch key and Look through key, on the Posing page.</li><li>Timing key, on the Trajectory page.</li></ul></li><li>A key another shortcut already uses in the same place is refused (&quot;X is taken by {name}&quot;). So are Studio&#39;s own Ctrl+C, V, X, D, Z and Y.</li><li>Reset this group puts them back.</li></ul><div class="tip custom-block"><p class="custom-block-title">Global keys through Studio</p><p>Every shortcut is also a Studio plugin action named &quot;AcesMotion: {name}&quot;, with no default key there. Bind it in Studio&#39;s own shortcut editor (File &gt; Customize Shortcuts); Settings &gt; Shortcuts says so under its header, with a tooltip.</p><ul><li>A key bound there works anywhere in Studio, even when no AcesMotion window has focus.</li><li>Studio runs it before AcesMotion sees it, so a plain letter or Space bound there may fire while you type. Pick one with Ctrl or Alt.</li><li>Plugin actions fire on press only. The hold keys (Space, P, I, Tab, J) fire their release when the plugin action is used.</li></ul></div><h4 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Scope</th><th>Works while</th></tr></thead><tbody><tr><td><strong>Timeline</strong></td><td>The Timeline has focus.</td></tr><tr><td><strong>Timeline (hover)</strong></td><td>The Timeline has focus, or the pointer is over it.</td></tr><tr><td><strong>Viewport</strong></td><td>No AcesMotion window has focus (the 3D view).</td></tr><tr><td><strong>Any</strong></td><td>Either the Timeline or the viewport.</td></tr><tr><td><strong>Inspector</strong></td><td>The Inspector window.</td></tr></tbody></table><h3 id="timeline" tabindex="-1">Timeline <a class="header-anchor" href="#timeline" aria-label="Permalink to &quot;Timeline&quot;">​</a></h3><h4 id="playback-and-navigation" tabindex="-1">Playback and navigation <a class="header-anchor" href="#playback-and-navigation" aria-label="Permalink to &quot;Playback and navigation&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Key</th><th>Action</th><th>Scope</th><th>Notes</th></tr></thead><tbody><tr><td><kbd>Space</kbd></td><td>Play or pause</td><td>Timeline (hover), viewport, Hub, Inspector</td><td>Tap plays or pauses. Hold and drag over the Timeline to pan.</td></tr><tr><td><kbd>Left</kbd> / <kbd>Right</kbd></td><td>Previous frame / Next frame</td><td>Timeline</td><td>Stops playback.</td></tr><tr><td><kbd>Up</kbd> / <kbd>Down</kbd></td><td>Previous key / Next key</td><td>Timeline</td><td>Of the whole scene.</td></tr><tr><td><kbd>Home</kbd> / <kbd>End</kbd></td><td>Go to start / Go to end</td><td>Timeline (hover)</td><td>Of the loop region when there is one.</td></tr><tr><td><kbd>Shift+I</kbd> / <kbd>Shift+O</kbd></td><td>Loop in / Loop out</td><td>Timeline (hover)</td><td>At the playhead.</td></tr></tbody></table><h4 id="view" tabindex="-1">View <a class="header-anchor" href="#view" aria-label="Permalink to &quot;View&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Key</th><th>Action</th><th>Scope</th><th>Notes</th></tr></thead><tbody><tr><td><kbd>F</kbd></td><td>Frame selected</td><td>Timeline</td><td>Selected keys, else the loop region, else all. In the curve graph, also the values.</td></tr><tr><td><kbd>A</kbd></td><td>Frame all</td><td>Timeline</td><td>In the curve graph, also the values.</td></tr><tr><td><kbd>E</kbd></td><td>Ease selected keys</td><td>Timeline</td><td>Opens or closes the Ease window.</td></tr><tr><td><kbd>Tab</kbd></td><td>Switch dope sheet and curves</td><td>Timeline</td><td>Dope sheet &gt; Ease view &gt; Channels view &gt; Dope sheet. In Split it swaps the lower part.</td></tr><tr><td><kbd>=</kbd> / <kbd>-</kbd></td><td>Zoom in / Zoom out</td><td>Timeline (hover)</td><td>Around the pointer (or the playhead).</td></tr></tbody></table><h4 id="keying" tabindex="-1">Keying <a class="header-anchor" href="#keying" aria-label="Permalink to &quot;Keying&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Key</th><th>Action</th><th>Scope</th><th>Notes</th></tr></thead><tbody><tr><td><kbd>K</kbd></td><td>Key selected</td><td>Timeline</td><td>Keys the selected rows at the playhead. With none selected, the picked joints or posed tracks, else the selected actors.</td></tr><tr><td><kbd>Shift+K</kbd></td><td>Key whole actor</td><td>Timeline (hover)</td><td>Every joint of the selected rigs, keyed or not (not their root). The root of any other actor.</td></tr></tbody></table><h4 id="editing-keys" tabindex="-1">Editing keys <a class="header-anchor" href="#editing-keys" aria-label="Permalink to &quot;Editing keys&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Key</th><th>Action</th><th>Scope</th><th>Notes</th></tr></thead><tbody><tr><td><kbd>Shift+C</kbd></td><td>Copy keys</td><td>Timeline (hover)</td><td>Keys, blocks, Camera switch keys and attach keys.</td></tr><tr><td><kbd>Shift+V</kbd></td><td>Paste keys</td><td>Timeline (hover)</td><td>At the playhead, onto what you selected last (a block&#39;s lane, a row, a key&#39;s row or an actor). Blocks, switch keys and attach keys too.</td></tr><tr><td><kbd>Shift+N</kbd></td><td>Paste keys mirrored</td><td>Timeline (hover)</td><td></td></tr><tr><td><kbd>Shift+D</kbd></td><td>Duplicate keys</td><td>Timeline (hover)</td><td>With blocks selected, duplicates the blocks instead. Keys and blocks selected together are duplicated together.</td></tr><tr><td><kbd>Del</kbd></td><td>Delete keys</td><td>Timeline (hover)</td><td>See below.</td></tr><tr><td><kbd>Backspace</kbd></td><td>Delete keys (Backspace)</td><td>Timeline (hover)</td><td>The same as Del (a Mac laptop has no Del key). It is its own shortcut, so it can be rebound or cleared.</td></tr><tr><td><kbd>[</kbd> / <kbd>]</kbd></td><td>Nudge keys left / right</td><td>Timeline (hover)</td><td>One frame.</td></tr><tr><td><kbd>Shift+[</kbd> / <kbd>Shift+]</kbd></td><td>Nudge keys 10 frames left / right</td><td>Timeline (hover)</td><td></td></tr><tr><td><kbd>Shift+Left</kbd> / <kbd>Shift+Right</kbd></td><td>Nudge keys left / right (arrow)</td><td>Timeline (focused)</td><td>One frame, like <kbd>[</kbd> <kbd>]</kbd>.</td></tr><tr><td><kbd>Esc</kbd></td><td>Clear key selection</td><td>Timeline (hover)</td><td>Clears the selected keys, blocks, switch keys, attach keys, marker and rows.</td></tr><tr><td><kbd>F2</kbd></td><td>Rename action track</td><td>Timeline</td><td>With one action track header selected, edits its name in place.</td></tr><tr><td>none</td><td>Select all keys</td><td>Timeline</td><td>Also in the Edit menu.</td></tr></tbody></table><p>What <kbd>Del</kbd> deletes:</p><ul><li>With blocks selected, it deletes the blocks instead. Keys and blocks selected together are deleted together.</li><li>With no keys or blocks selected, it deletes the selected marker.</li><li>Else it removes the selected rows&#39; tracks, as one undo step: property, object, joint and root rows as Remove from timeline, action tracks as Remove action track.</li><li>Actor rows stay; a note says to use their menu.</li><li>Keys on a locked track or actor are left and stay selected. The status bar names the lock (&quot;root is locked: 12 keys stayed selected. Unlock it to delete them.&quot;).</li></ul><h3 id="anywhere" tabindex="-1">Anywhere <a class="header-anchor" href="#anywhere" aria-label="Permalink to &quot;Anywhere&quot;">​</a></h3><p>These work with the Timeline or the viewport focused (scope Any), except Save version.</p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th><th>Notes</th></tr></thead><tbody><tr><td><kbd>Ctrl+Shift+K</kbd></td><td>Toggle auto-key</td><td></td></tr><tr><td><kbd>Ctrl+Shift+O</kbd></td><td>Toggle onion skin</td><td></td></tr><tr><td><kbd>R</kbd></td><td>Switch gizmo space</td><td>Local &gt; Parent &gt; World.</td></tr><tr><td><kbd>T</kbd></td><td>Switch gizmo handles</td><td>Move &amp; rotate and Resize. With separate handles: Move, Rotate, Resize.</td></tr><tr><td><kbd>P</kbd></td><td>Pin parts</td><td>Tap to pin or unpin the picked parts. Hold and click a part. Holds through a click into the viewport.</td></tr><tr><td><kbd>Shift+P</kbd></td><td>Clear all pins</td><td>Follows the pin key if rebound.</td></tr><tr><td><kbd>Shift+L</kbd></td><td>Lock picked</td><td>A Lock on each picked part, from the playhead to its next key (or a second).</td></tr><tr><td><kbd>Shift+M</kbd></td><td>Mirror posing</td><td></td></tr><tr><td><kbd>J</kbd></td><td>Trail timing (hold)</td><td>Also read by polling while the viewport has focus, so it can work there. If another binding owns <kbd>J</kbd> on your machine, rebind it (Settings &gt; Trajectory &gt; Timing key).</td></tr><tr><td><kbd>Alt+Shift+S</kbd></td><td>Save version</td><td>Anywhere in AcesMotion. A version of the open scene with an automatic name (Scene &gt; Save).</td></tr><tr><td>none</td><td>Open settings</td><td></td></tr><tr><td>none</td><td>Reset window layout</td><td></td></tr><tr><td>none</td><td>Toggle effect preview</td><td>Same as View &gt; Effect preview.</td></tr><tr><td>none</td><td>Toggle trails while scrubbing</td><td>Same as View &gt; Trails while scrubbing.</td></tr></tbody></table><h3 id="viewport" tabindex="-1">Viewport <a class="header-anchor" href="#viewport" aria-label="Permalink to &quot;Viewport&quot;">​</a></h3><h4 id="posing" tabindex="-1">Posing <a class="header-anchor" href="#posing" aria-label="Permalink to &quot;Posing&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Key</th><th>Action</th><th>Notes</th></tr></thead><tbody><tr><td><kbd>Shift+C</kbd></td><td>Copy pose</td><td></td></tr><tr><td><kbd>Shift+V</kbd></td><td>Paste pose</td><td></td></tr><tr><td><kbd>Shift+N</kbd></td><td>Paste pose mirrored</td><td></td></tr><tr><td><kbd>Shift+F</kbd></td><td>Flip pose</td><td>Also with the Timeline, Hub or Inspector focused; from the Timeline on the selected keys&#39; joints.</td></tr><tr><td><kbd>Shift+R</kbd></td><td>Reset to rest</td><td>Also with the Timeline, Hub or Inspector focused; from the Timeline on the selected keys&#39; joints.</td></tr><tr><td>none</td><td>Select mirror</td><td>Also in the Pose menu. Works from any AcesMotion window.</td></tr><tr><td><kbd>[</kbd> / <kbd>]</kbd></td><td>Pick the joint above / below</td><td></td></tr><tr><td><kbd>Tab</kbd></td><td>Temporary pivot (hold)</td><td></td></tr><tr><td><kbd>X</kbd></td><td>Switch IK / FK</td><td>Switches posing between FK and IK. Stays until pressed again.</td></tr><tr><td><kbd>Ctrl+[</kbd> / <kbd>Ctrl+]</kbd></td><td>Shorter / Longer IK chain</td><td></td></tr><tr><td><kbd>Esc</kbd></td><td>Let go of the picked joints</td><td>Cancels a gizmo drag first, then drops a path point pick, then the pick.</td></tr></tbody></table><h4 id="attaching-and-poses" tabindex="-1">Attaching and poses <a class="header-anchor" href="#attaching-and-poses" aria-label="Permalink to &quot;Attaching and poses&quot;">​</a></h4><p>These work in the viewport and the Timeline.</p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th><th>Notes</th></tr></thead><tbody><tr><td><kbd>Shift+G</kbd></td><td>Attach to</td><td>The picked part or actor follows what you click next, from the playhead.</td></tr><tr><td><kbd>Shift+Alt+G</kbd></td><td>Detach</td><td>At the playhead. It stays where it was.</td></tr><tr><td><kbd>Shift+Alt+A</kbd></td><td>Back to rig</td><td>Rig joints only. Snaps back into its place on the rig (Blend on the key eases it).</td></tr><tr><td>none</td><td>Back to rig where it is</td><td>Rig joints only. Rejoins its rig keeping where it is now. Bind it in Settings &gt; Shortcuts.</td></tr><tr><td><kbd>Alt+1</kbd> ... <kbd>Alt+9</kbd></td><td>Apply pose slot 1 ... 9</td><td>With <kbd>Shift</kbd> mirrored, with <kbd>Ctrl</kbd> to the whole actor.</td></tr><tr><td><kbd>Ctrl+Alt+P</kbd></td><td>Quick pose</td><td>The quick pose picker at the pointer.</td></tr></tbody></table><h4 id="camera" tabindex="-1">Camera <a class="header-anchor" href="#camera" aria-label="Permalink to &quot;Camera&quot;">​</a></h4><p><kbd>Q</kbd>, <kbd>Shift+Q</kbd> and <kbd>Ctrl+Shift+Q</kbd> work in the viewport and the Timeline. <kbd>F</kbd> and <kbd>Ctrl+F</kbd> work in the viewport.</p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th><th>Notes</th></tr></thead><tbody><tr><td><kbd>Q</kbd></td><td>Look through camera</td><td>Toggles look-through. It always turns it off, also while looking away.</td></tr><tr><td><kbd>Shift+Q</kbd></td><td>Align camera to view</td><td>Moves the selected camera actor (else the live one) to your view and keys it at the playhead.</td></tr><tr><td><kbd>Ctrl+Shift+Q</kbd></td><td>Pilot camera</td><td>Turns Pilot camera on (looking through first if needed) or off.</td></tr><tr><td><kbd>F</kbd></td><td>Focus camera on the pointer</td><td>Turns the camera to look at what&#39;s under the pointer, keeping position and roll (Reset roll when focusing levels it).</td></tr><tr><td><kbd>Ctrl+F</kbd></td><td>Focus camera and level it</td><td>As Focus camera on the pointer, and levels the roll to 0.</td></tr></tbody></table><ul><li>All five are ignored while a mouse button is held. For <kbd>Q</kbd> that is because Studio flies down with right mouse + <kbd>Q</kbd>.</li><li><kbd>Q</kbd> is also ignored with <kbd>Ctrl</kbd>, <kbd>Alt</kbd> or <kbd>Meta</kbd> held. While <kbd>Q</kbd> is held, the view stays still (Studio would fly it down).</li><li>When <kbd>Shift+Q</kbd> or <kbd>Ctrl+Shift+Q</kbd> can&#39;t run (the view is locked on the camera, no camera), the reason shows in the status bar.</li><li>Focus works with a camera picked (Move or Rotate gizmo), a camera selected in the Timeline or Hub, or the piloted camera. With no camera picked it does nothing.</li><li>Focus is keyed with Auto-key, as one undo step. While looking through, both Focus keys work only with Pilot camera on.</li></ul><h3 id="inspector" tabindex="-1">Inspector <a class="header-anchor" href="#inspector" aria-label="Permalink to &quot;Inspector&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Action</th><th>Scope</th><th>Notes</th></tr></thead><tbody><tr><td><kbd>K</kbd></td><td>Key property</td><td>Inspector (hover)</td><td>Keys the property row under the pointer.</td></tr><tr><td><kbd>Shift+C</kbd></td><td>Copy property value</td><td>Inspector (hover)</td><td>Copies the value of the property row under the pointer, else the picked row.</td></tr><tr><td><kbd>Shift+V</kbd></td><td>Paste property value</td><td>Inspector (hover)</td><td>Pastes onto the row under the pointer, else onto every picked row.</td></tr></tbody></table><h3 id="library" tabindex="-1">Library <a class="header-anchor" href="#library" aria-label="Permalink to &quot;Library&quot;">​</a></h3><p>These work in the Poses tab, on the pose under the pointer.</p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th><th>Notes</th></tr></thead><tbody><tr><td><kbd>Enter</kbd></td><td>Apply pose</td><td>With <kbd>Shift</kbd> mirrored, with <kbd>Ctrl</kbd> whole actor.</td></tr><tr><td><kbd>F2</kbd></td><td>Rename pose</td><td></td></tr><tr><td><kbd>Shift+D</kbd></td><td>Duplicate pose</td><td></td></tr><tr><td><kbd>Del</kbd> / <kbd>Backspace</kbd></td><td>Delete pose</td><td>Undo in the status line.</td></tr></tbody></table><h3 id="fixed-keys" tabindex="-1">Fixed keys <a class="header-anchor" href="#fixed-keys" aria-label="Permalink to &quot;Fixed keys&quot;">​</a></h3><p>Keys inside windows and menus. These can&#39;t be rebound.</p><h4 id="menus" tabindex="-1">Menus <a class="header-anchor" href="#menus" aria-label="Permalink to &quot;Menus&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><kbd>Esc</kbd></td><td>Closes the menu.</td></tr><tr><td><kbd>Up</kbd> / <kbd>Down</kbd></td><td>Move, skipping greyed items.</td></tr><tr><td><kbd>Return</kbd> / <kbd>Enter</kbd></td><td>Run the highlighted item or open its submenu.</td></tr><tr><td><kbd>Right</kbd></td><td>Opens a submenu.</td></tr><tr><td><kbd>Left</kbd></td><td>Closes a submenu.</td></tr><tr><td>Any other key</td><td>Closes the menu.</td></tr></tbody></table><p>With the mouse:</p><ul><li>A submenu opens on hover and stays open while you move into it, even across other items on the way. It closes a moment after you settle on another item.</li><li>In a narrow window, a submenu that can&#39;t fit beside its menu opens just below its item.</li><li>Tooltips of things under an open menu stay hidden.</li><li>Menu items whose name doesn&#39;t say what they do show a tooltip card while hovered (about 250 across the Timeline, viewport, Hub and Inspector menus).</li></ul><h4 id="fields-and-windows" tabindex="-1">Fields and windows <a class="header-anchor" href="#fields-and-windows" aria-label="Permalink to &quot;Fields and windows&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Where</th><th>Key</th><th>Action</th></tr></thead><tbody><tr><td>Text fields</td><td><kbd>Enter</kbd> / <kbd>Esc</kbd></td><td>Keeps / cancels (Inspector text, asset id, attribute name, rename boxes). Search boxes clear on <kbd>Esc</kbd>.</td></tr><tr><td>Number fields (scrub)</td><td><kbd>Shift</kbd></td><td>Finer.</td></tr><tr><td>Number fields (scrub)</td><td><kbd>Ctrl</kbd></td><td>Whole numbers.</td></tr><tr><td>Number fields (scrub)</td><td><kbd>Esc</kbd></td><td>Puts the value back.</td></tr><tr><td>Editor windows</td><td><kbd>Esc</kbd> during a drag</td><td>Cancels just that drag.</td></tr><tr><td>Editor windows</td><td><kbd>Enter</kbd></td><td>OK (unless a field is being typed in).</td></tr><tr><td>Editor windows</td><td><kbd>Esc</kbd></td><td>Cancel.</td></tr><tr><td>Editor windows</td><td><kbd>Del</kbd> / <kbd>Backspace</kbd></td><td>Removes the selected point or stop.</td></tr><tr><td>Editor windows</td><td><kbd>Ctrl+Z</kbd> / <kbd>Ctrl+Y</kbd></td><td>Step through the window&#39;s changes.</td></tr><tr><td>Editor windows</td><td><kbd>F2</kbd> / <kbd>Del</kbd> over a saved swatch</td><td>Rename / delete it.</td></tr><tr><td>Presets menu</td><td><kbd>Esc</kbd>, <kbd>Up</kbd>, <kbd>Down</kbd>, <kbd>Home</kbd>, <kbd>End</kbd>, <kbd>Enter</kbd></td><td></td></tr><tr><td>Ease canvas</td><td><kbd>Shift</kbd></td><td>Snaps a dragged handle to 0.05.</td></tr><tr><td>Ease canvas</td><td><kbd>Alt</kbd></td><td>Ignores snapping.</td></tr><tr><td>Sequence editor</td><td><kbd>Shift</kbd></td><td>Snaps a dragged point&#39;s time to 0.05.</td></tr><tr><td>Instance picker</td><td><kbd>Enter</kbd></td><td>Picks the first match.</td></tr><tr><td>Instance picker</td><td><kbd>Esc</kbd></td><td>Closes.</td></tr></tbody></table>',47)])])}const p=e(i,[["render",a]]);export{c as __pageData,p as default};
